import { useEffect, useState, type ComponentType } from 'react'
import {
  Activity, AlertCircle, Archive, BarChart3, ChevronDown, ChevronRight, CircleHelp, Copy,
  Database, FileText, GitBranch, LayoutDashboard, Menu, Network, Plus, Search, Settings,
  Shield, SlidersHorizontal, Sparkles, Trash2, Users, X, Zap, KeyRound, FlaskConical,
} from 'lucide-react'
import { analyze, api, detectInput } from './api/client'
import type { CaseRecord, Chain, InputKind, InvestigationResult } from './types'

type Tab = 'Overview' | 'Activity' | 'Counterparties' | 'Heuristics' | 'Raw Data'
const chains: { id: Chain; label: string; short: string }[] = [
  { id: 'auto', label: 'Auto', short: 'AUTO' }, { id: 'ethereum', label: 'Ethereum', short: 'ETH' },
  { id: 'base', label: 'Base', short: 'BASE' }, { id: 'bsc', label: 'BSC', short: 'BSC' },
  { id: 'solana', label: 'Solana', short: 'SOL' }, { id: 'bitcoin', label: 'Bitcoin', short: 'BTC' },
]
const nav = [
  { label: 'Dashboard', icon: LayoutDashboard }, { label: 'Cases', icon: Archive },
  { label: 'Explorer', icon: Search }, { label: 'Graph', icon: Network },
  { label: 'Heuristics', icon: Sparkles }, { label: 'Key Lab', icon: KeyRound }, { label: 'Entropy Intelligence', icon: FlaskConical }, { label: 'Settings', icon: Settings },
]

const emptyCase = (): CaseRecord => ({ id: crypto.randomUUID(), name: 'Untitled investigation', createdAt: new Date().toISOString(), primaryTarget: '', chain: 'auto', results: [], notes: '', graphState: { expanded: [] } })

export default function App() {
  const [input, setInput] = useState('')
  const [chain, setChain] = useState<Chain>('auto')
  const [cases, setCases] = useState<CaseRecord[]>([])
  const [activeCaseId, setActiveCaseId] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<Tab>('Overview')
  const [result, setResult] = useState<InvestigationResult | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [backendOnline, setBackendOnline] = useState<boolean | null>(null)
  const [advanced, setAdvanced] = useState(false)
  const [mobileNav, setMobileNav] = useState(false)
  const [derivationType, setDerivationType] = useState('ethereum')
  const [derivedCount, setDerivedCount] = useState(5)
  const [view, setView] = useState<'dashboard' | 'keylab' | 'entropy'>('dashboard')

  useEffect(() => { api.health().then(() => setBackendOnline(true)).catch(() => setBackendOnline(false)) }, [])
  const activeCase = cases.find(item => item.id === activeCaseId)
  const detected = input ? detectInput(input) : 'unknown'
  const detectedLabel = detected === 'mnemonic' ? 'BIP39 mnemonic' : detected === 'unknown' ? 'Input type pending' : detected.replace('-', ' ')

  const selectCase = (item: CaseRecord) => {
    setActiveCaseId(item.id); setResult(item.results[item.results.length - 1] || null); setInput(item.primaryTarget); setChain(item.chain as Chain); setError('')
  }
  const newCase = () => { const item = emptyCase(); setCases(prev => [...prev, item]); selectCase(item); setInput(''); setResult(null) }
  const deleteCase = (id: string) => { setCases(prev => prev.filter(item => item.id !== id)); if (activeCaseId === id) { setActiveCaseId(null); setResult(null) } }
  const renameCase = (id: string) => { const current = cases.find(item => item.id === id); const name = window.prompt('Case name', current?.name || 'Investigation'); if (name?.trim()) setCases(prev => prev.map(item => item.id === id ? { ...item, name: name.trim() } : item)) }

  const runAnalysis = async () => {
    if (!input.trim()) { setError('Enter an address or mnemonic to begin an investigation.'); return }
    setLoading(true); setError(''); setResult(null); setActiveTab('Overview')
    try {
      const next = await analyze({ input: input.trim(), chain, kind: detected as InputKind, derivationType, count: derivedCount })
      setResult(next)
      if (next.detectedKind === 'mnemonic') {
        // Do not leave a seed phrase visible in the UI after local derivation.
        setInput('')
      } else {
        const current = activeCase || emptyCase()
        const updated = { ...current, primaryTarget: next.target, chain: next.chain, results: [...current.results, next] }
        setCases(prev => prev.some(item => item.id === current.id) ? prev.map(item => item.id === current.id ? updated : item) : [...prev, updated])
        setActiveCaseId(current.id)
      }
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'The investigation could not be completed.') }
    finally { setLoading(false) }
  }
  const newCaseIfNeeded = () => { newCase() }

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><GitBranch size={18} /></div><div><strong>Chain-Trace</strong><span>FORENSICS CONSOLE</span></div><button className="mobile-close" onClick={() => setMobileNav(false)}><X size={17} /></button></div>
      <div className="sidebar-section"><span className="eyebrow">WORKSPACE</span>{nav.map(({ label, icon: Icon }) => <button key={label} className={`nav-item ${(label === 'Dashboard' && view === 'dashboard') || (label === 'Key Lab' && view === 'keylab') || (label === 'Entropy Intelligence' && view === 'entropy') ? 'active' : ''}`} onClick={() => { if (label === 'Key Lab') setView('keylab'); if (label === 'Entropy Intelligence') setView('entropy'); if (label === 'Dashboard') setView('dashboard'); setMobileNav(false) }}><Icon size={16} /><span>{label}</span>{label === 'Cases' && cases.length > 0 && <b>{cases.length}</b>}</button>)}</div>
      <div className="sidebar-bottom"><div className="privacy-card"><Shield size={16} /><div><strong>Local-first</strong><span>Data stays in this session</span></div></div><div className="backend-status"><i className={backendOnline ? 'online' : backendOnline === false ? 'offline' : ''} /> Backend {backendOnline ? 'connected' : backendOnline === false ? 'offline' : 'checking'}</div><span className="version">v0.2.0 · zero-key mode</span></div>
    </aside>
    {mobileNav && <div className="scrim" onClick={() => setMobileNav(false)} />}
    <main className="main-content">
      <header className="topbar"><button className="menu-button" onClick={() => setMobileNav(true)}><Menu size={19} /></button><div className="breadcrumb"><span>Workspace</span><ChevronRight size={13} /><strong>Dashboard</strong></div><div className="topbar-actions"><span className="secure-label"><Shield size={14} /> Session-only</span><button className="icon-button" title="Help"><CircleHelp size={18} /></button></div></header>
      <div className="content-wrap">
        {view === 'keylab' ? <KeyLabScreen /> : view === 'entropy' ? <EntropyIntelligenceScreen /> : <>
        <section className="hero"><div><span className="eyebrow accent">INVESTIGATION WORKSPACE</span><h1>Trace a target.</h1><p>One guided workflow for addresses, activity, and forensic signals.</p></div><div className="hero-meta"><div className="live-dot" /> <span>Local analysis ready</span></div></section>
        <section className="search-panel">
          <div className="search-label"><Search size={16} /><span>Universal investigation input</span><span className="input-type">{input ? detectedLabel : 'Address · transaction · mnemonic'}</span></div>
          <div className="search-row"><input value={input} onChange={event => setInput(event.target.value)} onKeyDown={event => event.key === 'Enter' && runAnalysis()} placeholder="Paste an address, transaction hash, or BIP39 mnemonic…" spellCheck={false} /><button className="analyze-button" onClick={runAnalysis} disabled={loading}>{loading ? <span className="spinner" /> : <Zap size={17} />}{loading ? 'Analyzing' : 'Analyze'}</button></div>
          <div className="search-footer"><label>Chain <select value={chain} onChange={event => setChain(event.target.value as Chain)}>{chains.map(item => <option key={item.id} value={item.id}>{item.label}</option>)}</select><ChevronDown size={13} /></label><button className="advanced-link" onClick={() => setAdvanced(true)}><SlidersHorizontal size={14} /> Advanced</button><button className="new-case" onClick={newCaseIfNeeded}><Plus size={15} /> New Case</button></div>
        </section>
        {error && <div className="error-banner"><AlertCircle size={17} /><span>{error}</span><button onClick={() => setError('')}><X size={15} /></button></div>}
        {result ? <InvestigationView result={result} tab={activeTab} setTab={setActiveTab} /> : <EmptyState onNewCase={newCaseIfNeeded} />}
        </>}
      </div>
    </main>
    <CasesDrawer cases={cases} activeId={activeCaseId} onSelect={selectCase} onNew={newCaseIfNeeded} onRename={renameCase} onDelete={deleteCase} />
    {advanced && <AdvancedModal result={result} input={input} chain={chain} derivationType={derivationType} setDerivationType={setDerivationType} derivedCount={derivedCount} setDerivedCount={setDerivedCount} onClose={() => setAdvanced(false)} />}
  </div>
}

function EntropyIntelligenceScreen() {
  const [tab, setTab] = useState<'Entropy Analysis' | 'Profiles' | 'Synthetic Exploit Replay' | 'Patch Validation' | 'Partial Recovery' | '256/256 Assurance' | 'Wallet Recovery'>('Entropy Analysis')
  const [software, setSoftware] = useState('Unknown')
  const [version, setVersion] = useState('')
  const [platform, setPlatform] = useState('Browser Extension')
  const [details, setDetails] = useState('')
  const [stateWidth, setStateWidth] = useState('')
  const [analysis, setAnalysis] = useState<any>(null)
  const [profiles, setProfiles] = useState<any[]>([])
  const [lab, setLab] = useState<any>(null)
  const [comparison, setComparison] = useState<any>(null)
  const [audit, setAudit] = useState<any>(null)
  const [source, setSource] = useState('import random\nseed = int(time.time())\nsecret = random.getrandbits(256)')
  const [model, setModel] = useState('20')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [estimate, setEstimate] = useState<any>(null)
  const [unknownWords, setUnknownWords] = useState(3)
  useEffect(() => { api.entropyProfiles().then((body: any) => setProfiles(body.profiles || [])).catch(() => undefined) }, [])
  const runAnalyze = async () => { setBusy(true); setError(''); try { setAnalysis(await api.entropyAnalyze({ provenance: { wallet_software: software === 'Unknown' ? null : software, wallet_version: version || null, platform, generator_details: details || null }, generator_state_width_bits: stateWidth ? Number(stateWidth) : null, software_status: details.toLowerCase().includes('patched') ? 'PATCHED' : 'UNKNOWN', wallet_generation_status: details.toLowerCase().includes('vulnerable') ? 'VULNERABLE' : 'UNKNOWN' })); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Entropy analysis failed.') } finally { setBusy(false) } }
  const generate = async () => { setBusy(true); setError(''); try { setLab(await api.entropyGenerate({ model })); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Synthetic fixture generation failed.') } finally { setBusy(false) } }
  const recover = async () => { if (!lab?.session_token) return; setBusy(true); try { setLab({ ...lab, recovery: await api.entropyRecover({ session_token: lab.session_token }) }) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Synthetic recovery failed.') } finally { setBusy(false) } }
  const runAudit = async () => { setBusy(true); setError(''); try { setAudit(await api.entropyValidate({ filename: 'synthetic-fixture.py', source })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Patch validation failed.') } finally { setBusy(false) } }
  const runEstimate = async () => { setBusy(true); setError(''); try { setEstimate(await api.entropyEstimate({ mnemonic_length: 12, known_word_count: 12 - unknownWords, unknown_word_count: unknownWords, known_positions: [], known_address_available: false, passphrase_known: true })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Estimate failed.') } finally { setBusy(false) } }
  return <section className="entropy-screen"><div className="keylab-hero"><div><span className="eyebrow accent">DEFENSIVE ENTROPY ANALYSIS</span><h1>Entropy Intelligence</h1><p>Separate mnemonic validity from generator provenance, effective entropy, and feasibility.</p></div><div className="lab-badge"><Shield size={16} /><span>ANALYSIS-FIRST</span></div></div>{error && <div className="error-banner"><AlertCircle size={17} /><span>{error}</span><button onClick={() => setError('')}><X size={15} /></button></div>}<div className="keylab-tabs">{(['Entropy Analysis', 'Profiles', 'Synthetic Exploit Replay', 'Patch Validation', 'Partial Recovery', '256/256 Assurance', 'Wallet Recovery'] as const).map(item => <button key={item} className={tab === item ? 'selected' : ''} onClick={() => setTab(item)}>{item}</button>)}</div>
    {tab === 'Wallet Recovery' && <WalletRecoveryPanel />}
    {tab === '256/256 Assurance' && <EntropyAssurancePanel />}
    {tab === 'Entropy Analysis' && <div className="entropy-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">WALLET PROVENANCE</span><h3>Analyze before computation</h3></div><FlaskConical size={17} /></div><label>Wallet software<select value={software} onChange={event => setSoftware(event.target.value)}><option>Unknown</option><option>Electrum</option><option>Browser wallet</option><option>Custom generator</option></select></label><label>Version<input value={version} onChange={event => setVersion(event.target.value)} placeholder="optional" /></label><label>Platform<select value={platform} onChange={event => setPlatform(event.target.value)}><option>Browser Extension</option><option>Native Application</option><option>Browser / WASM</option><option>Unknown</option></select></label><label>Known generator details<textarea value={details} onChange={event => setDetails(event.target.value)} placeholder="e.g. uses OS CSPRNG, timestamp seed, Math.random…" /></label><label>Generator state width<input value={stateWidth} onChange={event => setStateWidth(event.target.value)} placeholder="optional bits" inputMode="numeric" /></label><button className="analyze-button wide" onClick={runAnalyze} disabled={busy}>{busy ? <span className="spinner" /> : <Zap size={16} />}{busy ? 'Analyzing' : 'Analyze provenance'}</button><div className="lab-warning blue"><Shield size={14} /><span>Mnemonic text alone cannot establish the quality of its original entropy.</span></div></div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">RESULT</span><h3>Risk and feasibility</h3></div></div>{analysis ? <><div className="entropy-metrics"><div><span>Classification</span><strong>{analysis.estimate?.classification}</strong></div><div><span>Effective entropy</span><strong>{analysis.estimate?.estimated_effective_entropy_bits ?? 'Unknown'} bits</strong></div><div><span>Candidate space</span><strong>{analysis.estimate?.candidate_space_display}</strong></div><div><span>Feasibility</span><strong>{analysis.feasibility?.feasibility_class}</strong></div></div><div className="entropy-callout"><strong>Recommended response</strong><p>{analysis.recommended_response}</p></div><div className="entropy-callout"><strong>Evidence confidence · {Math.round((analysis.generator_confidence || 0) * 100)}%</strong><p>{analysis.effective_entropy_impact}</p></div></> : <div className="no-data"><FlaskConical size={17} />Provide generator evidence to classify the scenario.</div>}</div></div>}
    {tab === 'Profiles' && <div className="panel profiles-panel"><div className="panel-title"><div><span className="eyebrow">DEFENSIVE REGISTRY</span><h3>Known generator weaknesses</h3></div><span className="local-tag">{profiles.length} profiles</span></div><div className="profile-list">{profiles.map(profile => <div className="profile-row" key={profile.id}><div><strong>{profile.name}</strong><span>{profile.wallet_or_tool} · {profile.affected_platform}</span></div><div><b>{profile.weakness_class}</b><span>{profile.effective_entropy_description}</span></div><div><b>{profile.old_generated_wallets_remain_exposed ? 'Old wallets remain exposed' : 'No legacy exposure'}</b><span>{profile.affected_period || 'Period requires evidence'}</span></div></div>)}</div></div>}
    {tab === 'Synthetic Exploit Replay' && <div className="entropy-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">CHAIN-TRACE-OWNED FIXTURE</span><h3>Synthetic exploit replay</h3></div><span className="local-tag">No external targets</span></div><div className="lab-warning blue"><Database size={14} /><span>Recovery requires a session token issued by this generator. Public addresses cannot be submitted.</span></div><label>Weakness model<select value={model} onChange={event => setModel(event.target.value)}><option value="16">16-bit seed</option><option value="20">20-bit seed</option><option value="24">24-bit seed</option><option value="32">32-bit seed</option><option value="timestamp">Timestamp-window seed</option><option value="repeated">Deterministic repeated seed</option></select></label><button className="analyze-button wide" onClick={generate} disabled={busy}>{busy ? 'Generating' : 'Generate test wallet'}</button>{lab && <><div className="target-address">Synthetic address: {lab.target_address}</div><div className="entropy-metrics compact"><div><span>Effective entropy</span><strong>{lab.actual_effective_entropy_bits} bits</strong></div><div><span>Search space</span><strong>{lab.candidate_space_display}</strong></div></div><button className="ghost-button" onClick={recover} disabled={busy || !lab.recovery_allowed}>Run controlled recovery</button></>}</div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">RECOVERY OUTPUT</span><h3>Verification</h3></div></div>{lab?.recovery ? <div className="entropy-callout"><strong>Recovered synthetic fixture</strong><p>{lab.recovery.candidates_tested} candidates tested · {lab.recovery.verification ? 'verification passed' : 'not verified'}</p><small>Secret material remains redacted.</small></div> : <div className="no-data">Generate a local fixture to begin.</div>}</div></div>}
    {tab === 'Patch Validation' && <div className="entropy-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">STATIC ANALYSIS</span><h3>Validate generator source</h3></div></div><textarea className="source-editor" value={source} onChange={event => setSource(event.target.value)} spellCheck={false} /><button className="analyze-button wide" onClick={runAudit} disabled={busy}>{busy ? 'Scanning' : 'Run static checks'}</button><p className="muted-note">Positive CSPRNG evidence is useful, but passing statistical tests is not proof of cryptographic security.</p></div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">FINDINGS</span><h3>{audit?.risk || 'Awaiting source'}</h3></div></div>{audit ? <><div className="finding-stack">{audit.findings?.map((item: any, index: number) => <div className="entropy-finding" key={index}><b>{item.risk} · line {item.line}</b><span>{item.evidence}</span><small>{item.recommendation}</small></div>)}</div>{audit.positive_evidence?.length > 0 && <p className="positive-evidence">Positive evidence: {audit.positive_evidence.map((item: any) => item.label).join(', ')}</p>}</> : <div className="no-data">Static inspection never executes the supplied source.</div>}</div></div>}
    {tab === 'Partial Recovery' && <div className="entropy-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">LEGITIMATE SELF-RECOVERY</span><h3>Partial mnemonic estimate</h3></div></div><label>Unknown word count<input type="number" min="0" max="11" value={unknownWords} onChange={event => setUnknownWords(Number(event.target.value))} /></label><button className="analyze-button wide" onClick={runEstimate} disabled={busy}>{busy ? 'Estimating' : 'Estimate complexity'}</button><div className="lab-warning"><AlertCircle size={14} /><span>This estimates search complexity only; it does not accept or search an external wallet target.</span></div></div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">ESTIMATE</span><h3>Checksum-aware candidate space</h3></div></div>{estimate ? <div className="entropy-metrics"><div><span>Raw combinations</span><strong>{estimate.raw_word_combination_count.toLocaleString()}</strong></div><div><span>Checksum reduced</span><strong>{estimate.checksum_reduced_estimate.toLocaleString()}</strong></div><div><span>Class</span><strong>{estimate.feasibility_class}</strong></div></div> : <div className="no-data">Set the number of unknown words to estimate.</div>}</div></div>}
  </section>
}

function EntropyAssurancePanel() {
  const [tab, setTab] = useState<'Generator Audit' | 'Self Audit' | 'Runtime Environment' | '256 vs Reduced Entropy' | 'Assurance Report'>('Generator Audit')
  const [source, setSource] = useState('')
  const [audit, setAudit] = useState<any>(null)
  const [report, setReport] = useState<any>(null)
  const [probe, setProbe] = useState<any>(null)
  const [comparison, setComparison] = useState<any>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const secureFixture = 'def generate():\n    try:\n        entropy = secrets.token_bytes(32)\n    except Exception as exc:\n        raise RuntimeError("CSPRNG unavailable") from exc\n    return entropy'
  const auditGenerator = async (value: string) => { setBusy(true); setError(''); try { setReport(await api.assuranceAuditGenerator({ source: value, filename: 'authorized-generator.py', implementation: 'Audited wallet generator', platform: 'native Python', runtime: 'CPython' })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Assurance audit failed.') } finally { setBusy(false) } }
  const runSelfAudit = async () => { setBusy(true); setError(''); try { setReport(await api.assuranceSelfAudit({ include_mnemonic: false })); setTab('Assurance Report') } catch (reason) { setError(reason instanceof Error ? reason.message : 'Self-audit failed.') } finally { setBusy(false) } }
  const runSourceAudit = async () => { setBusy(true); setError(''); try { setAudit(await api.assuranceAuditSource({ source, filename: 'authorized-generator.py', implementation: 'Audited wallet generator', platform: 'selected environment', runtime: 'selected runtime' })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Source audit failed.') } finally { setBusy(false) } }
  const runProbe = async () => { setBusy(true); setError(''); try { setProbe(await api.assuranceRuntimeProbe({ environment: 'python-native', runtime: 'CPython', api: 'secrets.token_bytes', requested_bytes: 32 })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Runtime probe failed.') } finally { setBusy(false) } }
  const runCompare = async (mode: string) => { setBusy(true); setError(''); try { setComparison(await api.assuranceCompare({ mode })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Comparison failed.') } finally { setBusy(false) } }
  const checks = report?.checks || []
  return <div className="assurance-panel"><div className="assurance-tabs">{(['Generator Audit', 'Self Audit', 'Runtime Environment', '256 vs Reduced Entropy', 'Assurance Report'] as const).map(item => <button key={item} className={tab === item ? 'selected' : ''} onClick={() => setTab(item)}>{item}</button>)}</div>{error && <div className="error-banner"><AlertCircle size={17} /><span>{error}</span><button onClick={() => setError('')}><X size={15} /></button></div>}
    {tab === 'Generator Audit' && <div className="assurance-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">AUTHORIZED SOURCE REVIEW</span><h3>Generator Audit</h3></div><Shield size={17} /></div><textarea className="source-editor" value={source} onChange={event => setSource(event.target.value)} placeholder={secureFixture} spellCheck={false} /><button className="analyze-button wide" onClick={runSourceAudit} disabled={busy}>{busy ? 'Auditing' : 'Audit source path'}</button><p className="muted-note">Static evidence is conservative. A 32-byte output is not proof of 256 bits of entropy.</p>{audit && <div className="audit-summary"><span>Source</span><strong>{audit.source_kind}</strong><span>Maximum effective</span><strong>{audit.maximum_effective_bits ?? 'unknown'} bits</strong><span>Failure policy</span><strong>{audit.failure_policy}</strong></div>}</div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">DATA FLOW</span><h3>Source to sink</h3></div></div>{audit ? <><div className="flow-list">{audit.data_flow?.map((item: string, index: number) => <div key={index}><i>{index + 1}</i><span>{item}</span></div>)}</div><div className={`assurance-banner ${audit.assurance === 'FAILED' ? 'fail' : ''}`}><strong>{audit.assurance}</strong><span>{audit.claim?.statement}</span></div></> : <div className="no-data">Audit an authorized generator snippet to inspect entropy preservation.</div>}</div></div>}
    {tab === 'Self Audit' && <div className="panel assurance-card"><div className="panel-title"><div><span className="eyebrow accent">CHAIN-TRACE GENERATOR ASSURANCE</span><h3>Known-good local construction</h3></div><FlaskConical size={17} /></div><p className="assurance-copy">Runs the local reference generator with exactly 32 bytes from Python’s cryptographic randomness API, validates BIP39, then discards the fixture.</p><div className="assurance-summary-grid"><div><span>Entropy requested</span><strong>256 bits</strong></div><div><span>Source</span><strong>OS CSPRNG</strong></div><div><span>Consumed</span><strong>256 bits</strong></div><div><span>Discarded</span><strong>0 bits</strong></div><div><span>BIP39</span><strong>ENT 256 · CS 8</strong></div><div><span>Mnemonic</span><strong>24 words</strong></div></div><button className="analyze-button" onClick={runSelfAudit} disabled={busy}>{busy ? 'Validating' : 'Run self-audit'}</button><div className="lab-warning blue"><Shield size={14} /><span>No mnemonic, entropy bytes, private key, or seed is returned or persisted.</span></div></div>}
    {tab === 'Runtime Environment' && <div className="entropy-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">RUNTIME PROBE</span><h3>Native environment</h3></div></div><div className="audit-summary"><span>Environment</span><strong>python-native</strong><span>API</span><strong>secrets.token_bytes</strong><span>Request</span><strong>32 bytes</strong></div><button className="analyze-button wide" onClick={runProbe} disabled={busy}>{busy ? 'Probing' : 'Probe CSPRNG'}</button></div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">RESULT</span><h3>{probe?.status || 'Awaiting probe'}</h3></div></div>{probe ? <div className="entropy-metrics"><div><span>API available</span><strong>{probe.api_available ? 'YES' : 'NO'}</strong></div><div><span>Request succeeded</span><strong>{probe.request_succeeded ? 'YES' : 'NO'}</strong></div><div><span>Bytes returned</span><strong>{probe.bytes_returned}</strong></div><div><span>Fallback</span><strong>{probe.fallback_activated ? 'ACTIVATED' : 'NONE'}</strong></div></div> : <div className="no-data">A probe verifies operation only; it does not prove min-entropy.</div>}</div></div>}
    {tab === '256 vs Reduced Entropy' && <div className="compare-grid">{(['standard', 'expanded', 'truncated'] as const).map(mode => <button key={mode} className="compare-card" onClick={() => runCompare(mode)}><span className="eyebrow">{mode === 'standard' ? '256/256 GOOD' : mode === 'expanded' ? '256/32 BROKEN' : '256/64 BROKEN'}</span><strong>{mode === 'standard' ? 'OS CSPRNG → 32 bytes → BIP39' : mode === 'expanded' ? '32-bit seed → SHA256 → 256-bit output' : '256 random bits → retain 64 bits → SHA256'}</strong><small>Run comparison</small></button>)}</div>}
    {tab === 'Assurance Report' && <div className="panel assurance-card"><div className="panel-title"><div><span className="eyebrow">256/256 ENTROPY ASSURANCE</span><h3>{report?.overall_assurance || 'No report yet'}</h3></div><Shield size={17} /></div>{report ? <><div className="assurance-summary-grid"><div><span>Nominal entropy</span><strong>{report.nominal_entropy_bits} bits</strong></div><div><span>Requested CSPRNG</span><strong>{report.source_bits_requested ?? 'unknown'} bits</strong></div><div><span>Maximum preserved</span><strong>{report.maximum_effective_bits ?? 'unknown'} bits</strong></div><div><span>Source assurance</span><strong>{report.entropy_source_assurance}</strong></div><div><span>Implementation</span><strong>{report.implementation_assurance}</strong></div><div><span>Environment</span><strong>{report.environment_assurance}</strong></div></div><div className="checklist">{checks.map((check: any) => <div key={check.id} className={`check-row ${check.status.toLowerCase()}`}><b>{check.status}</b><span>{check.label}</span><small>{check.evidence}</small></div>)}</div><div className="entropy-callout"><strong>Effective entropy target</strong><p>{report.claim?.statement}</p></div></> : <div className="no-data">Run Self Audit or Generator Audit to produce a sanitized report.</div>}</div>}
    {comparison && <div className="panel comparison-result"><strong>{comparison.status} · maximum effective entropy {comparison.maximum_effective_bits} bits</strong><span>{comparison.warning}</span></div>}
  </div>
}

function WalletRecoveryPanel() {
  const [view, setView] = useState<'Recovery Assessment' | 'Derivation Explorer' | 'Mnemonic Recovery' | 'Recovery Report'>('Recovery Assessment')
  const [hasAddress, setHasAddress] = useState(true)
  const [hasSeed, setHasSeed] = useState(true)
  const [hasPartial, setHasPartial] = useState(false)
  const [hasPrivateKey, setHasPrivateKey] = useState(false)
  const [knownWallet, setKnownWallet] = useState(true)
  const [knownGenerator, setKnownGenerator] = useState(false)
  const [generatorSource, setGeneratorSource] = useState('')
  const [network, setNetwork] = useState('ethereum')
  const [address, setAddress] = useState('')
  const [mnemonic, setMnemonic] = useState('')
  const [partial, setPartial] = useState('')
  const [passphrase, setPassphrase] = useState('')
  const [passphraseComponents, setPassphraseComponents] = useState('')
  const [passphraseYears, setPassphraseYears] = useState('')
  const [passphraseSuffixes, setPassphraseSuffixes] = useState('')
  const [passphraseCapVariants, setPassphraseCapVariants] = useState(false)
  const [profileIds, setProfileIds] = useState<string[]>([])
  const [gapLimit, setGapLimit] = useState(20)
  const [maxSeedCandidates, setMaxSeedCandidates] = useState(8)
  const [maxRuntimeSeconds, setMaxRuntimeSeconds] = useState(30)
  const [session, setSession] = useState<any>(null)
  const [assessment, setAssessment] = useState<any>(null)
  const [derived, setDerived] = useState<any>(null)
  const [mnemonicEstimate, setMnemonicEstimate] = useState<any>(null)
  const [report, setReport] = useState<any>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const evidence = { known_addresses: hasAddress && address ? [address] : [], network, wallet_application: knownWallet ? 'Owner-specified wallet' : null, complete_mnemonic: hasSeed && mnemonic ? mnemonic : null, partial_mnemonic: hasPartial && partial ? partial : null, passphrase_known: Boolean(passphrase || passphraseComponents), passphrase_hints: passphrase ? [passphrase] : [], passphrase_components: passphraseComponents.split(',').map(item => item.trim()).filter(Boolean), passphrase_years: passphraseYears.split(',').map(item => Number(item.trim())).filter(item => Number.isFinite(item)), passphrase_suffixes: passphraseSuffixes.split(',').map(item => item.trim()).filter(Boolean), passphrase_capitalization_variants: passphraseCapVariants, private_key_available: hasPrivateKey, generator_source: knownGenerator && generatorSource ? generatorSource : null }
  const budget = { max_seed_candidates: maxSeedCandidates, max_pbkdf2_operations: maxSeedCandidates, max_paths_per_seed: 24, max_child_derivations: 180, max_chain_queries: 0, max_runtime_seconds: maxRuntimeSeconds, max_memory_mb: 256, max_kdf_work: maxSeedCandidates * 2048 }
  const runAssessment = async () => { setBusy(true); setError(''); try { const next: any = await api.walletRecoveryAnalyze({ evidence, budget }); setAssessment(next); setProfileIds((next.matched_profiles || []).map((profile: any) => profile.id)) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Recovery assessment failed.') } finally { setBusy(false) } }
  const createSession = async () => { setBusy(true); setError(''); try { const next = await api.walletRecoverySession({ evidence }); setSession(next); setView('Derivation Explorer') } catch (reason) { setError(reason instanceof Error ? reason.message : 'Owner session could not be created.') } finally { setBusy(false) } }
  const runDerivation = async () => { if (!session?.session_token) { await createSession(); return } setBusy(true); setError(''); try { setDerived(await api.walletRecoveryDerive({ session_token: session.session_token, networks: [network], profile_ids: profileIds, account_start: 0, account_count: 1, index_start: 0, index_count: gapLimit, passphrase, budget: { ...budget, max_paths_per_seed: Math.max(7, gapLimit * 7), max_child_derivations: Math.max(7, gapLimit * 7) } })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Derivation exploration failed.') } finally { setBusy(false) } }
  const runMnemonicEstimate = async () => { setBusy(true); setError(''); try { setMnemonicEstimate(await api.walletRecoveryAnalyzeMnemonic({ mnemonic_length: 24, partial_mnemonic: partial, known_word_count: partial ? partial.split(/\s+/).filter(Boolean).length : 23, known_positions: [], expected_address_available: hasAddress })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Mnemonic analysis failed.') } finally { setBusy(false) } }
  const runReport = async () => { setBusy(true); setError(''); try { setReport(await api.walletRecoveryBuildPlan({ evidence })) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Recovery plan failed.') } finally { setBusy(false) } }
  const checks = [['Wallet address', hasAddress, setHasAddress], ['Seed phrase', hasSeed, setHasSeed], ['Some seed words missing', hasPartial, setHasPartial], ['Private key', hasPrivateKey, setHasPrivateKey], ['Original wallet/software known', knownWallet, setKnownWallet], ['Original generator/source known', knownGenerator, setKnownGenerator]] as const
  return <div className="recovery-panel"><div className="recovery-tabs">{(['Recovery Assessment', 'Derivation Explorer', 'Mnemonic Recovery', 'Recovery Report'] as const).map(item => <button key={item} className={view === item ? 'selected' : ''} onClick={() => setView(item)}>{item}</button>)}</div>{error && <div className="error-banner"><AlertCircle size={17} /><span>{error}</span><button onClick={() => setError('')}><X size={15} /></button></div>}
    {view === 'Recovery Assessment' && <div className="recovery-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">OWNER EVIDENCE</span><h3>What do you still have?</h3></div><Shield size={17} /></div><div className="evidence-checks">{checks.map(([label, checked, setter]) => <label key={label}><input type="checkbox" checked={checked} onChange={event => setter(event.target.checked)} /><span>{label}</span></label>)}</div><label>Known network<select value={network} onChange={event => setNetwork(event.target.value)}><option value="ethereum">Ethereum / EVM</option><option value="bitcoin">Bitcoin</option><option value="solana">Solana</option></select></label>{hasAddress && <label>Known public address<input value={address} onChange={event => setAddress(event.target.value)} placeholder="owner-supplied address" spellCheck={false} /></label>}{hasSeed && <label>Complete mnemonic · active memory only<textarea value={mnemonic} onChange={event => setMnemonic(event.target.value)} placeholder="Paste only into this local session" spellCheck={false} /></label>}{hasPartial && <label>Partial mnemonic<textarea value={partial} onChange={event => setPartial(event.target.value)} placeholder="Use ? for missing words" spellCheck={false} /></label>}{hasSeed && <label>BIP39 passphrase · optional<input value={passphrase} onChange={event => setPassphrase(event.target.value)} type="password" autoComplete="off" /></label>}{knownGenerator && <label>Authorized generator/source<textarea value={generatorSource} onChange={event => setGeneratorSource(event.target.value)} placeholder="Paste source only for this active session" spellCheck={false} /></label>}<button className="analyze-button wide" onClick={runAssessment} disabled={busy}>{busy ? 'Assessing' : 'Choose recovery path'}</button><div className="lab-warning blue"><Shield size={14} /><span>Recovery is owner-controlled. No arbitrary private-key search or blockchain lookup is available.</span></div></div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">DIAGNOSIS</span><h3>{assessment?.classification || 'Awaiting evidence'}</h3></div></div>{assessment ? <><div className="entropy-callout"><strong>{assessment.diagnosis}</strong><p>{assessment.feasibility?.explanation}</p></div><div className="audit-summary"><span>Recommended path</span><strong>{assessment.recommended_path}</strong><span>Candidate space before constraints</span><strong>{assessment.candidate_space?.candidate_space_before_constraints?.toLocaleString?.() || 'not justified'}</strong><span>After checksum</span><strong>{assessment.candidate_space?.candidate_space_after_checksum?.toLocaleString?.() || 'not applicable'}</strong><span>Estimated derivations</span><strong>{assessment.candidate_space?.estimated_derivations?.toLocaleString?.() || 'not attempted'}</strong><span>Strongest verification</span><strong>{assessment.candidate_space?.strongest_verification_evidence || 'none'}</strong></div>{assessment.matched_profiles?.length > 0 && <div className="entropy-callout"><strong>Matched wallet profiles</strong><p>{assessment.matched_profiles.map((profile: any) => profile.name).join(' · ')}</p></div>}</> : <div className="no-data">The engine chooses a bounded path from the evidence you retain.</div>}</div></div>}
    {view === 'Derivation Explorer' && <div className="recovery-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">LOCAL ONLY</span><h3>Derivation Explorer</h3></div><FlaskConical size={17} /></div><p className="assurance-copy">Compare common wallet paths against an address you already know belongs to this wallet.</p><label>Address gap limit<input type="number" min="1" max="20" value={gapLimit} onChange={event => setGapLimit(Math.max(1, Math.min(20, Number(event.target.value))))} /></label><div className="audit-summary"><span>Network</span><strong>{network}</strong><span>Selected profiles</span><strong>{profileIds.length || 'standard defaults'}</strong></div><button className="analyze-button wide" onClick={runDerivation} disabled={busy || !mnemonic}>{busy ? 'Deriving' : 'Explore bounded paths'}</button>{!session && <button className="ghost-button" onClick={createSession} disabled={busy || !mnemonic}>Create owner session</button>}</div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">PUBLIC IDENTIFIERS</span><h3>{derived?.status || 'Not attempted'}</h3></div></div>{derived ? <div className="derivation-list">{derived.identifiers?.map((item: any, index: number) => <div key={index} className={item.matched ? 'matched' : ''}><span>{item.path}</span><strong>{item.address}</strong><b>{item.matched ? 'MATCH' : 'NO MATCH'}</b></div>)}</div> : <div className="no-data">No mnemonic or session has been used.</div>}</div></div>}
    {view === 'Mnemonic Recovery' && <div className="recovery-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">FEASIBILITY FIRST</span><h3>Partial mnemonic</h3></div></div><label>Partial words<textarea value={partial} onChange={event => { setPartial(event.target.value); setHasPartial(true) }} placeholder="23 known words plus ? for the missing word" spellCheck={false} /></label><button className="analyze-button wide" onClick={runMnemonicEstimate} disabled={busy}>{busy ? 'Calculating' : 'Calculate valid candidates'}</button><div className="lab-warning"><AlertCircle size={14} /><span>Candidate generation is not started automatically. Checksum filtering is applied before feasibility is reported.</span></div></div><div className="panel entropy-results"><div className="panel-title"><div><span className="eyebrow">CHECKSUM-AWARE ESTIMATE</span><h3>{mnemonicEstimate?.feasibility?.classification || 'Awaiting input'}</h3></div></div>{mnemonicEstimate ? <div className="entropy-metrics"><div><span>Unknown words</span><strong>{mnemonicEstimate.unknown_word_count}</strong></div><div><span>Raw combinations</span><strong>{mnemonicEstimate.raw_word_combination_count.toLocaleString()}</strong></div><div><span>Checksum reduced</span><strong>{mnemonicEstimate.checksum_reduced_candidate_count.toLocaleString()}</strong></div><div><span>Effective bits</span><strong>{mnemonicEstimate.feasibility?.effective_bits?.toFixed(1)}</strong></div></div> : <div className="no-data">Enter the evidence you possess to estimate the valid candidate population.</div>}</div></div>}
    {view === 'Recovery Report' && <div className="panel assurance-card"><div className="panel-title"><div><span className="eyebrow">OWNER-CONTROLLED PLAN</span><h3>{report?.classification || 'No plan yet'}</h3></div><Shield size={17} /></div>{report ? <><div className="checklist">{report.ordered_steps?.map((step: string, index: number) => <div className="check-row pass" key={index}><b>{index + 1}</b><span>{step}</span><small>Owner confirmation required</small></div>)}</div><div className="entropy-callout"><strong>Blocked operations</strong><p>{report.blocked_operations?.join(' · ')}</p></div></> : <><p className="assurance-copy">Build a plan from the evidence currently held in this session. Reports never contain secrets.</p><button className="analyze-button" onClick={runReport} disabled={busy}>{busy ? 'Planning' : 'Build recovery plan'}</button></>}</div>}
  </div>
}

function KeyLabScreen() {
  const [tab, setTab] = useState<'Vanity Generator' | 'Benchmark Lab' | 'Synthetic Search' | 'Split-Key' | 'Results'>('Vanity Generator')
  const [capabilities, setCapabilities] = useState<any>(null)
  const [pattern, setPattern] = useState('1A')
  const [addressType, setAddressType] = useState('p2pkh')
  const [workers, setWorkers] = useState(1)
  const [vanityJob, setVanityJob] = useState<any>(null)
  const [vanityResult, setVanityResult] = useState<any>(null)
  const [bench, setBench] = useState<any>(null)
  const [benchEngine, setBenchEngine] = useState('coincurve')
  const [synthetic, setSynthetic] = useState<any>(null)
  const [syntheticRange, setSyntheticRange] = useState(50)
  const [syntheticPosition, setSyntheticPosition] = useState('random')
  const [splitResult, setSplitResult] = useState<any>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  useEffect(() => { api.keylabCapabilities().then(setCapabilities).catch(reason => setError(reason instanceof Error ? reason.message : 'Key Lab capabilities unavailable.')) }, [])
  useEffect(() => {
    if (!vanityJob?.id || ['found', 'completed', 'cancelled', 'failed'].includes(vanityJob.state)) return
    const timer = window.setInterval(() => api.keylabJob(vanityJob.id).then((next: any) => { setVanityJob(next); if (next.result) setVanityResult(next.result) }).catch(() => undefined), 500)
    return () => window.clearInterval(timer)
  }, [vanityJob?.id, vanityJob?.state])
  const runVanity = async () => { setBusy(true); setError(''); setVanityResult(null); try { const job = await api.keylabVanityJob({ address_type: addressType, pattern, worker_count: workers, max_runtime_seconds: 30, case_sensitive: false, wildcard: false }); setVanityJob(job); setTab('Results') } catch (reason) { setError(reason instanceof Error ? reason.message : 'Vanity generation failed.') } finally { setBusy(false) } }
  const runBenchmark = async () => { setBusy(true); setError(''); try { setBench(await api.keylabBenchmark({ engine: benchEngine, stages: ['all'], range_size: 250, warmup_count: 1, sample_count: 3, worker_count: 1 })); setTab('Results') } catch (reason) { setError(reason instanceof Error ? reason.message : 'Benchmark failed.') } finally { setBusy(false) } }
  const runSynthetic = async () => { setBusy(true); setError(''); try { setSynthetic(await api.keylabSynthetic({ range_size: syntheticRange, target_position: syntheticPosition === 'random' ? null : Number(syntheticPosition), worker_count: 1, engine: 'coincurve' })); setTab('Results') } catch (reason) { setError(reason instanceof Error ? reason.message : 'Synthetic search failed.') } finally { setBusy(false) } }
  const runSplit = async () => { setBusy(true); setError(''); try { setSplitResult(await api.keylabSplitKey({ address_type: addressType, pattern })); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Split-key request failed.') } finally { setBusy(false) } }
  return <section className="keylab-screen"><div className="keylab-hero"><div><span className="eyebrow accent">LOCAL BITCOIN KEY LABORATORY</span><h1>Generate. Measure. Verify.</h1><p>Cryptographic experiments and new vanity keypairs, with no blockchain or external service calls.</p></div><div className="lab-badge"><KeyRound size={16} /><span>OFFLINE BY DESIGN</span></div></div>{error && <div className="error-banner"><AlertCircle size={17} /><span>{error}</span><button onClick={() => setError('')}><X size={15} /></button></div>}<div className="keylab-tabs">{(['Vanity Generator', 'Benchmark Lab', 'Synthetic Search', 'Split-Key', 'Results'] as const).map(item => <button key={item} className={tab === item ? 'selected' : ''} onClick={() => setTab(item)}>{item}</button>)}</div>{tab === 'Vanity Generator' && <div className="lab-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">NEW KEYPAIR SEARCH</span><h3>Vanity Generator</h3></div><span className="local-tag"><Shield size={12} /> Local-only</span></div><label>Address type<select value={addressType} onChange={event => setAddressType(event.target.value)}><option value="p2pkh">P2PKH</option><option value="p2wpkh">P2WPKH · native SegWit</option></select></label><label>Prefix pattern<input value={pattern} onChange={event => setPattern(event.target.value)} placeholder="1A" spellCheck={false} /><small>Prefix matching. Use an easy prefix for local validation.</small></label><label>Workers<select value={workers} onChange={event => setWorkers(Number(event.target.value))}><option value={1}>Auto · 1 worker</option><option value={2}>2 workers</option><option value={4}>4 workers</option></select></label><button className="analyze-button wide" onClick={runVanity} disabled={busy || !pattern}>{busy ? <span className="spinner" /> : <Zap size={16} />}{busy ? 'Starting search' : 'Generate Vanity Address'}</button><div className="lab-warning"><AlertCircle size={14} /><span>Private keys are never persisted by Chain-Trace. Reveal and export only when you are ready.</span></div></div><LabInfo capabilities={capabilities} /></div>}{tab === 'Benchmark Lab' && <div className="lab-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">REPRODUCIBLE MEASUREMENT</span><h3>Benchmark Lab</h3></div><BarChart3 size={17} /></div><label>Engine<select value={benchEngine} onChange={event => setBenchEngine(event.target.value)}><option value="coincurve">Coincurve · libsecp256k1</option><option value="bitcoinlib">bitcoinlib reference</option><option value="compare">Compare all</option></select></label><div className="stage-list"><span>Stages measured</span><div><i>ECC public key</i><i>SHA-256</i><i>RIPEMD-160</i><i>HASH160</i><i>Address encoding</i><i>Full pipeline</i></div></div><button className="analyze-button wide" onClick={runBenchmark} disabled={busy}>{busy ? <span className="spinner" /> : <BarChart3 size={16} />}{busy ? 'Measuring' : 'Run calibrated benchmark'}</button><p className="muted-note">Correctness vectors run before timing. Results are saved locally under data/keylab/benchmarks.</p></div><LabInfo capabilities={capabilities} /></div>}{tab === 'Synthetic Search' && <div className="lab-grid"><div className="panel lab-form"><div className="panel-title"><div><span className="eyebrow">LABORATORY MODE</span><h3>Sequential Search</h3></div><span className="local-tag"><Shield size={12} /> Synthetic only</span></div><div className="lab-warning blue"><Database size={14} /><span>Target is generated inside this Chain-Trace session. Arbitrary external addresses are rejected.</span></div><label>Range size<input type="number" min="2" max="100000" value={syntheticRange} onChange={event => setSyntheticRange(Math.max(2, Math.min(100000, Number(event.target.value))))} /></label><label>Target position<select value={syntheticPosition} onChange={event => setSyntheticPosition(event.target.value)}><option value="random">Random</option>{Array.from({ length: Math.min(syntheticRange, 10) }, (_, index) => <option key={index} value={index}>{index}</option>)}</select></label><button className="analyze-button wide" onClick={runSynthetic} disabled={busy}>{busy ? <span className="spinner" /> : <Search size={16} />}{busy ? 'Running experiment' : 'Run Experiment'}</button></div><LabInfo capabilities={capabilities} /></div>}{tab === 'Split-Key' && <div className="panel disabled-lab"><div className="finding-icon"><KeyRound size={18} /></div><div><span className="eyebrow">CAPABILITY GATE</span><h3>Split-key vanity generation is disabled</h3><p>The current installed bindings do not provide a reviewed public-key contribution workflow. Chain-Trace will not ship uncertain cryptography. The endpoint returns an explicit disabled capability response.</p><button className="ghost-button" onClick={runSplit} disabled={busy}>Check capability</button>{splitResult && <pre className="raw-data">{JSON.stringify(splitResult, null, 2)}</pre>}</div></div>}{tab === 'Results' && <KeyLabResults vanityJob={vanityJob} vanityResult={vanityResult} benchmark={bench} synthetic={synthetic} onCancel={() => vanityJob?.id && api.keylabCancelJob(vanityJob.id).then(setVanityJob)} />}</section>
}

function LabInfo({ capabilities }: { capabilities: any }) { return <div className="panel lab-info"><div className="panel-title"><div><span className="eyebrow">CAPABILITIES</span><h3>Safe operating envelope</h3></div><Shield size={17} /></div><div className="cap-row"><span>Network access</span><strong>Disabled</strong></div><div className="cap-row"><span>ECC engine</span><strong>Coincurve / libsecp256k1</strong></div><div className="cap-row"><span>Reference engine</span><strong>{capabilities?.engines?.includes('bitcoinlib') ? 'bitcoinlib' : 'Unavailable'}</strong></div><div className="cap-row"><span>Address formats</span><strong>P2PKH · P2WPKH</strong></div><div className="cap-row"><span>Split-key</span><strong className="disabled-text">Disabled</strong></div><div className="lab-note"><FileText size={14} /><span>Generated secrets are not logged or written to disk. Benchmark telemetry contains no private-key material.</span></div></div> }

function KeyLabResults({ vanityJob, vanityResult, benchmark, synthetic, onCancel }: { vanityJob: any; vanityResult: any; benchmark: any; synthetic: any; onCancel: () => void }) { const [revealed, setRevealed] = useState(false); const copyPrivate = () => vanityResult?.private_key && navigator.clipboard?.writeText(vanityResult.private_key); const exportPrivate = () => { if (!vanityResult?.private_key) return; const blob = new Blob([`${vanityResult.address}\n${vanityResult.private_key}\n`], { type: 'text/plain' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `chain-trace-${vanityResult.address}.txt`; link.click(); URL.revokeObjectURL(link.href) }; return <div className="results-stack">{vanityJob && <div className="panel lab-result"><div className="result-title"><div><span className="eyebrow">VANITY GENERATOR</span><h3>{vanityJob.state === 'found' ? 'MATCH FOUND' : `Search ${vanityJob.state}`}</h3></div>{['queued', 'running'].includes(vanityJob.state) && <button className="ghost-button" onClick={onCancel}>Cancel</button>}</div>{vanityJob.state === 'found' && vanityResult ? <div className="secret-grid"><div><span>Address</span><strong className="mono">{vanityResult.address}</strong></div><div><span>Public key</span><strong className="mono">{vanityResult.public_key}</strong></div><div className="private-result"><span>Private key · reveal once</span><strong className="mono">{revealed ? vanityResult.private_key : '••••••••••••••••••••••••••••••••'}</strong><div className="secret-actions"><button className="ghost-button" onClick={() => setRevealed(true)} disabled={revealed}>Reveal once</button><button className="ghost-button" onClick={copyPrivate} disabled={!revealed}>Copy</button><button className="ghost-button" onClick={exportPrivate} disabled={!revealed}>Export</button></div></div><small className="secret-note">Chain-Trace will not save this private key. Secure it before leaving this session.</small></div> : <div className="progress-reading"><Activity size={16} /><span>{vanityJob.state === 'running' ? 'Searching fresh keypairs locally…' : 'Job queued…'}</span></div>}</div>}{benchmark && <div className="panel lab-result"><div className="result-title"><div><span className="eyebrow">BENCHMARK LAB</span><h3>Correctness-gated measurements</h3></div><span className="local-tag">{benchmark.engine}</span></div><div className="benchmark-summary"><span>Oracle</span><strong>All vectors passed</strong><span>Samples</span><strong>{benchmark.sample_count}</strong><span>Range</span><strong>{benchmark.range_size.toLocaleString()}</strong></div><div className="benchmark-table"><div className="bench-row bench-head"><span>Stage</span><span>Ops/sec</span><span>Median</span><span>Workers</span></div>{benchmark.results.map((item: any) => <div className="bench-row" key={item.stage}><span>{item.stage}</span><span>{Math.round(item.ops_per_second).toLocaleString()}</span><span>{(item.median * 1000).toFixed(2)} ms</span><span>{item.worker_count}</span></div>)}</div></div>}{synthetic && <div className="panel lab-result"><div className="result-title"><div><span className="eyebrow">SYNTHETIC SEARCH</span><h3>{synthetic.verification ? 'Target recovered' : 'Experiment incomplete'}</h3></div><span className="local-tag">{synthetic.status}</span></div><div className="benchmark-summary"><span>Range</span><strong>{synthetic.range_size}</strong><span>Checked</span><strong>{synthetic.candidates_checked}</strong><span>Rate</span><strong>{Math.round(synthetic.candidates_per_second).toLocaleString()}/sec</strong><span>Verification</span><strong>{synthetic.verification ? 'PASS' : 'FAIL'}</strong></div><div className="mono target-address">Target address: {synthetic.target_address}</div></div>}{!vanityJob && !benchmark && !synthetic && <div className="panel no-data"><KeyRound size={19} /><span>Run a Key Lab experiment to see results here.</span></div>}</div> }

function EmptyState({ onNewCase }: { onNewCase: () => void }) { return <section className="empty-state"><div className="empty-icon"><Activity size={24} /></div><h2>Start an investigation</h2><p>Enter a public address above to see a concise forensic summary, activity, counterparties, and heuristic signals.</p><div className="empty-hints"><span><Shield size={14} /> No external keys required</span><span><Database size={14} /> Supports EVM · Solana · Bitcoin</span></div><button className="ghost-button" onClick={onNewCase}><Plus size={15} /> Create a case first</button></section> }

function InvestigationView({ result, tab, setTab }: { result: InvestigationResult; tab: Tab; setTab: (tab: Tab) => void }) {
  const labels: Tab[] = ['Overview', 'Activity', 'Counterparties', 'Heuristics', 'Raw Data']
  return <section className="investigation"><div className="result-head"><div><div className="target-line"><span className={`chain-badge ${result.chain}`}>{result.chain === 'ethereum' ? 'ETH' : result.chain.slice(0, 4).toUpperCase()}</span><span className="target-kind">{result.detectedKind === 'mnemonic' ? 'LOCAL DERIVATION' : 'TARGET ANALYSIS'}</span></div><h2>{result.target}</h2><div className="result-sub"><span className={`status-dot ${result.risk}`} />{result.status}<span className="separator">·</span>{result.chain} <Copy size={13} /></div></div><div className={`risk-pill ${result.risk}`}><span>{result.risk === 'clear' ? 'Low signal' : result.risk === 'review' ? 'Review recommended' : 'Partial data'}</span></div></div><div className="tabbar">{labels.map(label => <button key={label} className={tab === label ? 'selected' : ''} onClick={() => setTab(label)}>{label}{label === 'Activity' && result.transactions.length > 0 && <small>{result.transactions.length}</small>}</button>)}</div>{tab === 'Overview' && <Overview result={result} />}{tab === 'Activity' && <ActivityTab result={result} />}{tab === 'Counterparties' && <CounterpartyTab result={result} />}{tab === 'Heuristics' && <HeuristicTab result={result} />}{tab === 'Raw Data' && <pre className="raw-data">{JSON.stringify(result.raw, null, 2)}</pre>}</section>
}

function Overview({ result }: { result: InvestigationResult }) { const cards = [{ label: 'Native balance', value: result.balance, icon: BarChart3 }, { label: 'Transactions', value: result.transactionCount, icon: Activity }, { label: 'Incoming', value: result.incomingCount, icon: ArrowIn }, { label: 'Outgoing', value: result.outgoingCount, icon: ArrowOut }, { label: 'Counterparties', value: result.counterparties.length || undefined, icon: Users }, { label: 'Cluster links', value: result.clusterAssociations.length || undefined, icon: Network }]; return <><div className="metric-grid">{cards.map(({ label, value, icon: Icon }) => <Metric key={label} label={label} value={value} icon={Icon} />)}</div><div className="overview-grid"><div className="panel summary-panel"><div className="panel-title"><div><span className="eyebrow">FORENSIC SUMMARY</span><h3>What we found</h3></div><FileText size={17} /></div><p>{result.detectedKind === 'mnemonic' ? 'Public addresses were derived locally. The mnemonic was not persisted and is not included in this case.' : result.partial ? 'The target was analyzed, but one or more providers returned partial data. Review the raw response for details.' : result.transactionCount ? `Observed ${result.transactionCount} transaction${result.transactionCount === 1 ? '' : 's'} across the selected chain.` : 'The backend returned no transaction activity for this target.'}</p><div className="summary-chips"><span className="chip"><Shield size={13} /> {result.detectedKind === 'mnemonic' ? 'Private input handled locally' : 'No keys required'}</span><span className="chip"><Activity size={13} /> {result.chain.toUpperCase()}</span></div></div><GraphPanel result={result} /></div></> }
function Metric({ label, value, icon: Icon }: { label: string; value?: string | number; icon: ComponentType<{ size?: string | number }> }) { return <div className="metric-card"><div className="metric-icon"><Icon size={16} /></div><div><span>{label}</span><strong>{value === undefined || value === null ? 'Not available' : typeof value === 'number' ? value.toLocaleString() : value}</strong></div></div> }
function ActivityTab({ result }: { result: InvestigationResult }) { return <div className="panel table-panel"><div className="panel-title"><div><span className="eyebrow">OBSERVED ACTIVITY</span><h3>Transaction timeline</h3></div><span className="table-count">{result.transactions.length} records</span></div>{result.transactions.length ? <div className="table-scroll"><table><thead><tr><th>Time</th><th>Direction</th><th>Counterparty</th><th>Amount</th><th>Transaction hash</th><th>Status</th></tr></thead><tbody>{result.transactions.map((item, index) => <tr key={`${item.hash}-${index}`}><td>{item.time}</td><td><span className="direction">{item.direction}</span></td><td className="mono">{item.counterparty}</td><td>{item.amount}</td><td className="mono hash">{item.hash}</td><td><span className="table-status">{item.status}</span></td></tr>)}</tbody></table></div> : <div className="no-data"><Activity size={20} /><span>No transaction records were returned.</span></div>}</div> }
function CounterpartyTab({ result }: { result: InvestigationResult }) { return <div className="panel table-panel"><div className="panel-title"><div><span className="eyebrow">INTERACTION MAP</span><h3>Counterparties</h3></div><span className="table-count">ranked by available data</span></div>{result.counterparties.length ? <div className="counterparty-list">{result.counterparties.map((item, index) => <div className="counterparty" key={item}><span className="rank">0{index + 1}</span><div className="node-dot" /><span className="mono">{item}</span><span className="frequency">Observed</span></div>)}</div> : <div className="no-data"><Users size={20} /><span>Counterparty details are not available for this response.</span></div>}</div> }
function HeuristicTab({ result }: { result: InvestigationResult }) { const findings = [{ title: 'CoinJoin likelihood', value: result.coinjoinLikelihood }, { title: 'CIOH associations', value: result.ciohAssociations?.join(', ') }, { title: 'Possible change addresses', value: result.changeAddresses?.join(', ') }]; return <div className="heuristic-grid">{findings.map(item => <div className="panel finding" key={item.title}><div className="finding-icon"><Sparkles size={16} /></div><div><span className="eyebrow">{item.title}</span><p>{item.value || 'Not available'}</p></div></div>)}{!result.coinjoinLikelihood && !result.ciohAssociations?.length && !result.changeAddresses?.length && <div className="panel no-data"><Sparkles size={20} /><span>No heuristic findings are available for this target.</span></div>}</div> }
function ArrowIn(props: { size?: string | number }) { return <span className="arrow-icon in">↓</span> }
function ArrowOut(props: { size?: string | number }) { return <span className="arrow-icon out">↑</span> }
function GraphPanel({ result }: { result: InvestigationResult }) { const nodes = result.counterparties.slice(0, 4); return <div className="panel graph-panel"><div className="panel-title"><div><span className="eyebrow">RELATIONSHIP GRAPH</span><h3>Target network</h3></div><button className="text-button">Expand <ChevronRight size={14} /></button></div><div className="graph-canvas"><div className="graph-lines">{nodes.map((_, index) => <i key={index} style={{ transform: `rotate(${index * 45 - 70}deg)` }} />)}</div><div className="graph-node target"><Shield size={16} /><span>Target</span></div>{nodes.map((node, index) => <div className="graph-node satellite" key={node} style={{ left: `${18 + index * 21}%`, top: index % 2 ? '68%' : '14%' }}><span>{String(index + 1).padStart(2, '0')}</span></div>)}{!nodes.length && <div className="graph-empty">Counterparty edges appear here when returned by the provider.</div>}</div></div> }

function CasesDrawer({ cases, activeId, onSelect, onNew, onRename, onDelete }: { cases: CaseRecord[]; activeId: string | null; onSelect: (item: CaseRecord) => void; onNew: () => void; onRename: (id: string) => void; onDelete: (id: string) => void }) { return <aside className="case-drawer"><div className="drawer-head"><div><span className="eyebrow">CASES</span><h3>Session investigations</h3></div><button className="icon-button" onClick={onNew} title="New case"><Plus size={17} /></button></div>{cases.length ? cases.map(item => <div className={`case-row ${activeId === item.id ? 'active' : ''}`} key={item.id} onClick={() => onSelect(item)}><div className="case-symbol"><Archive size={14} /></div><div className="case-info"><strong>{item.name}</strong><span>{item.primaryTarget ? `${item.chain} · ${item.results.length} result${item.results.length === 1 ? '' : 's'}` : 'No target yet'}</span></div><div className="case-actions"><button onClick={event => { event.stopPropagation(); onRename(item.id) }}><FileText size={13} /></button><button onClick={event => { event.stopPropagation(); onDelete(item.id) }}><Trash2 size={13} /></button></div></div>) : <div className="no-cases"><Archive size={18} /><span>Your current cases will appear here.</span><button onClick={onNew}>Create case</button></div>}</aside> }

function AdvancedModal({ result, input, chain, derivationType, setDerivationType, derivedCount, setDerivedCount, onClose }: { result: InvestigationResult | null; input: string; chain: Chain; derivationType: string; setDerivationType: (value: string) => void; derivedCount: number; setDerivedCount: (value: number) => void; onClose: () => void }) { return <div className="modal-backdrop" onClick={onClose}><div className="advanced-modal" onClick={event => event.stopPropagation()}><div className="modal-head"><div><span className="eyebrow accent">ADVANCED CONTROLS</span><h2>Investigation parameters</h2></div><button className="icon-button" onClick={onClose}><X size={18} /></button></div><div className="advanced-fields"><label>Explicit chain override<select value={chain} onChange={() => undefined} disabled><option>{chain}</option></select><small>Controlled from the main workflow.</small></label><label>Derivation path<select value={derivationType} onChange={event => setDerivationType(event.target.value)}><option value="ethereum">Ethereum · m/44'/60'/0'</option><option value="bip44">Bitcoin Legacy · m/44'/0'/0'</option><option value="bip49">Bitcoin SegWit · m/49'/0'/0'</option><option value="bip84">Bitcoin Native SegWit · m/84'/0'/0'</option><option value="solana">Solana · m/44'/501'/0'</option></select></label><label>Derived address count<input type="number" min="1" max="100" value={derivedCount} onChange={event => setDerivedCount(Math.max(1, Math.min(100, Number(event.target.value))))} /></label><div className="advanced-readonly"><span>Raw request input</span><code>{input || 'No input submitted'}</code></div><div className="advanced-readonly"><span>Raw API response</span><pre>{result ? JSON.stringify(result.raw, null, 2) : 'No response yet'}</pre></div></div><div className="modal-foot"><span><Shield size={14} /> Mnemonics are never stored in cases.</span><button className="ghost-button" onClick={onClose}>Done</button></div></div></div> }
